def artifact(i,rel,kind,desc,command=None,result=None):
 p=A/rel;x={'id':i,'kind':kind,'path':p.as_posix(),'sha256':h(p),'description':desc}
 if kind=='execution':x.update(command=command,result=result,environment=env)
 artifacts.append(x);return i
