def raw(prefix):return [{'path':x['path'],'sha256':x['sha256_rawbytes'],'inspected_pointers':x['inspected_pointers']} for x in CAT if prefix in x['path']]
def claim(i,kind,statement,loc,evidence,scope,arts,expected=None,observed=None,details=None,den=None,raws=None):
 x={'id':i,'kind':kind,'statement':statement,'location':loc,'status':'verified','evidence':evidence,'artifact_ids':arts,'scope':scope}
 if kind in ['software','empirical','numeric']:
  x['verification']={'method':'executed','expected':expected,'observed':observed,'details':details}
  if kind=='empirical':x['verification']['denominators']=den
 if raws:x['raw_evidence']=raws
 claims.append(x)
